    },
    {
      "name": "test_one_dimensional_palindrome",
      "intent": "If H == 1 (single row), assert the output is 'YES' exactly when the row string can be rearranged into a palindrome (at most one odd count). If W == 1 (single column), assert the output is 'YES' exactly when the column string (concatenated cells) can be rearranged into a palindrome."
    },
    {
      "name": "test_2x2_bruteforce",
      "intent": "For grids with H == 2 and W == 2, try all row swaps (identity and swap) and column swaps (identity and swap) and check if any combination makes the grid symmetric. Assert the output matches the result."
    },
    {
      "name": "test_already_symmetric",
      "intent": "Check if the original grid (without any swaps) is symmetric: for all i,j, grid[i][j] == grid[H-1-i][W-1-j]. If it is symmetric, assert the output is 'YES'."
    },
    {
      "name": "test_distinct_rows_or_columns_impossible",
      "intent": "If H > 1 and all rows have distinct multisets (each row's Counter is unique), assert the output is 'NO'. Similarly, if W > 1 and all columns have distinct multisets, assert the output is 'NO'."
    },
    {
      "name": "test_single_cell_always_yes",
      "intent": "If H == 1 and W == 1, assert the output is 'YES'."
    },
    {
      "name": "test_all_same_letter_yes",
      "intent": "If every cell in the grid contains the same letter, assert the output is 'YES'."
    }
  ]
}

