def test_bruteforce_small(run, x):
    lines = x.strip().split('\n')
    H, W = map(int, lines[0].split())
    if H > 6 or W > 6:
        return  # skip large grids
    grid = [list(row.strip()) for row in lines[1:1+H]]
    from itertools import permutations
    # brute-force all row and column permutations
    rows = list(range(H))
    cols = list(range(W))
    possible = False
    for rperm in permutations(rows):
        for cperm in permutations(cols):
            ok = True
            for i in range(H):
                for j in range(W):
                    a = grid[rperm[i]][cperm[j]]
                    b = grid[rperm[H-1-i]][cperm[W-1-j]]
                    if a != b:
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                possible = True
                break
        if possible:
            break
    out = run(x).strip()
    if possible:
        assert out == 'YES', f'Should be YES, got {out}'
    else:
        assert out == 'NO', f'Should be NO, got {out}'

def test_output_format(run, x):
    out = run(x)
    stripped = out.strip()
    assert stripped in ('YES', 'NO'), f'Output must be YES or NO, got {stripped!r}'
    # Ensure it ends with newline (raw output is stripped plus newline)
    assert out.endswith('\n'), 'Output must end with newline'
    # Also ensure no extra whitespace besides trailing newline
    assert out.rstrip('\n') == stripped, 'No extra whitespace allowed besides newline'

def test_letter_parity(run, x):
    out = run(x).strip()
    if out != 'YES':
        return
    lines = x.strip().split('\n')
    H, W = map(int, lines[0].split())
    grid = [list(row.strip()) for row in lines[1:1+H]]
    from collections import Counter
    freq = Counter()
    for row in grid:
        freq.update(row)
    odd_cnt = sum(1 for v in freq.values() if v % 2 == 1)
    if (H * W) % 2 == 0:
        assert odd_cnt == 0, f'All frequencies must be even for even total cells, odd counts: {odd_cnt}'
    else:
        assert odd_cnt == 1, f'Exactly one letter frequency must be odd for odd total cells, odd counts: {odd_cnt}'

def test_row_column_multiset_parity(run, x):
    out = run(x).strip()
    if out != 'YES':
        return
    lines = x.strip().split('\n')
    H, W = map(int, lines[0].split())
    grid = [list(row.strip()) for row in lines[1:1+H]]
    from collections import Counter
    # rows
    row_counts = Counter(tuple(sorted(row)) for row in grid)
    odd_rows = sum(1 for v in row_counts.values() if v % 2 == 1)
    if H % 2 == 0:
        assert odd_rows == 0, f'Row multisets must appear even times for even H, odd rows: {odd_rows}'
    else:
        assert odd_rows <= 1, f'At most one row multiset can appear odd times for odd H, odd rows: {odd_rows}'
    # columns
    cols = [''.join(grid[i][j] for i in range(H)) for j in range(W)]
    col_counts = Counter(tuple(sorted(col)) for col in cols)
    odd_cols = sum(1 for v in col_counts.values() if v % 2 == 1)
    if W % 2 == 0:
        assert odd_cols == 0, f'Column multisets must appear even times for even W, odd cols: {odd_cols}'
    else:
        assert odd_cols <= 1, f'At most one column multiset can appear odd times for odd W, odd cols: {odd_cols}'

def test_one_dimensional_palindrome(run, x):
    lines = x.strip().split('\n')
    H, W = map(int, lines[0].split())
    if H == 1:
        row = lines[1].strip()
        from collections import Counter
        freq = Counter(row)
        odd = sum(1 for v in freq.values() if v % 2 == 1)
        expected = odd <= 1
        out = run(x).strip()
        if expected:
            assert out == 'YES', f'Single row can be rearranged to palindrome, expected YES, got {out}'
        else:
            assert out == 'NO', f'Single row cannot be rearranged to palindrome, expected NO, got {out}'
    if W == 1:
        col = ''.join(line.strip() for line in lines[1:1+H])
        from collections import Counter
        freq = Counter(col)
        odd = sum(1 for v in freq.values() if v % 2 == 1)
        expected = odd <= 1
        out = run(x).strip()
        if expected:
            assert out == 'YES', f'Single column can be rearranged to palindrome, expected YES, got {out}'
        else:
            assert out == 'NO', f'Single column cannot be rearranged to palindrome, expected NO, got {out}'

def test_2x2_bruteforce(run, x):
    lines = x.strip().split('\n')
    H, W = map(int, lines[0].split())
    if H != 2 or W != 2:
        return
    grid = [list(row.strip()) for row in lines[1:1+H]]
    # try all row swaps (identity, swap) and column swaps (identity, swap)
    possible = False
    for rswap in (False, True):
        rows = [0,1] if not rswap else [1,0]
        for cswap in (False, True):
            cols = [0,1] if not cswap else [1,0]
            ok = True
            for i in range(2):
                for j in range(2):
                    a = grid[rows[i]][cols[j]]
                    b = grid[rows[1-i]][cols[1-j]]
                    if a != b:
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                possible = True
                break
        if possible:
            break
    out = run(x).strip()
    if possible:
        assert out == 'YES', f'2x2 should be YES, got {out}'
    else:
        assert out == 'NO', f'2x2 should be NO, got {out}'

def test_already_symmetric(run, x):
    lines = x.strip().split('\n')
    H, W = map(int, lines[0].split())
    grid = [list(row.strip()) for row in lines[1:1+H]]
    symmetric = True
    for i in range(H):
        for j in range(W):
            if grid[i][j] != grid[H-1-i][W-1-j]:
                symmetric = False
                break
        if not symmetric:
            break
    if symmetric:
        out = run(x).strip()
        assert out == 'YES', f'Grid is already symmetric, expected YES, got {out}'

def test_distinct_rows_or_columns_impossible(run, x):
    lines = x.strip().split('\n')
    H, W = map(int, lines[0].split())
    grid = [list(row.strip()) for row in lines[1:1+H]]
    from collections import Counter
    # rows
    if H > 1:
        row_counts = Counter(tuple(sorted(row)) for row in grid)
        if all(v == 1 for v in row_counts.values()):  # all distinct multisets
            out = run(x).strip()
            assert out == 'NO', f'All row multisets distinct, expected NO, got {out}'
    # columns
    if W > 1:
        cols = [''.join(grid[i][j] for i in range(H)) for j in range(W)]
        col_counts = Counter(tuple(sorted(col)) for col in cols)
        if all(v == 1 for v in col_counts.values()):  # all distinct multisets
            out = run(x).strip()
            assert out == 'NO', f'All column multisets distinct, expected NO, got {out}'

def test_single_cell_always_yes(run, x):
    lines = x.strip().split('\n')
    H, W = map(int, lines[0].split())
    if H == 1 and W == 1:
        out = run(x).strip()
        assert out == 'YES', f'Single cell grid must be YES, got {out}'

def test_all_same_letter_yes(run, x):
    lines = x.strip().split('\n')
    H, W = map(int, lines[0].split())
    grid = [list(row.strip()) for row in lines[1:1+H]]
    first = grid[0][0]
    same = all(cell == first for row in grid for cell in row)
    if same:
        out = run(x).strip()
        assert out == 'YES', f'All cells same letter, must be YES, got {out}'

