def test_output_format(run, x):
    output = run(x).strip()
    assert output in ('sjfnb', 'cslnb'), f"Output must be exactly 'sjfnb' or 'cslnb', got '{output}'"

def test_all_zero(run, x):
    parts = x.strip().split()
    n = int(parts[0])
    a = list(map(int, parts[1:]))
    if all(v == 0 for v in a):
        assert run(x).strip() == 'cslnb', "All piles zero -> Tokitsukaze cannot move, must output 'cslnb'"

def test_ideal_sequence(run, x):
    parts = x.strip().split()
    n = int(parts[0])
    a = list(map(int, parts[1:]))
    if len(a) == n:
        s = sorted(a)
        if s == list(range(n)):  # exactly 0,1,2,...,n-1
            assert run(x).strip() == 'cslnb', f"Sorted piles are 0..{n-1}, must output 'cslnb'"

def test_consecutive_from_one(run, x):
    parts = x.strip().split()
    n = int(parts[0])
    a = list(map(int, parts[1:]))
    if len(a) == n:
        s = sorted(a)
        if s == list(range(1, n+1)):  # exactly 1,2,...,n
            expected = 'sjfnb' if n % 2 == 1 else 'cslnb'
            assert run(x).strip() == expected, f"Sorted piles are 1..{n}, must output '{expected}'"

def test_small_bruteforce(run, x):
    # Only run exhaustive simulation when n ≤ 5 and each a_i ≤ 4
    parts = x.strip().split()
    n = int(parts[0])
    a = list(map(int, parts[1:]))
    if n <= 5 and max(a) <= 4:
        # Helper to simulate optimal play
        from functools import lru_cache
        def winner(state):
            state = tuple(sorted(state))
            @lru_cache(None)
            def dfs(s):
                if all(v == 0 for v in s):
                    return False  # current player loses (no move)
                moves = []
                for i, v in enumerate(s):
                    if v > 0:
                        new = list(s)
                        new[i] = v - 1
                        new.sort()
                        # check duplicate after move
                        if len(set(new)) == len(new):
                            moves.append(tuple(new))
                if not moves:
                    return False  # all moves lead to immediate loss
                # optimal play: if any move leads to opponent losing, current wins
                for mv in moves:
                    if not dfs(mv):
                        return True
                return False
            return dfs(state)
        correct = 'sjfnb' if winner(tuple(a)) else 'cslnb'
        assert run(x).strip() == correct, f"Brute-force simulation says winner is '{correct}'"

