def test_single_pile(run, x):
    parts = x.strip().split()
    n = int(parts[0])
    a = list(map(int, parts[1:]))
    if n == 1:
        # According to the plan, parity decides: odd stones -> sjfnb, even -> cslnb
        # But the specification does not state this, so we only verify via brute-force for small a_i
        if a[0] <= 10:  # small enough to simulate
            from functools import lru_cache
            def winner(state):
                state = tuple(state)
                @lru_cache(None)
                def dfs(s):
                    if s[0] == 0:
                        return False
                    # only one pile, reduce by 1 if it doesn't create duplicate (always true for one pile)
                    new = (s[0]-1,)
                    if len(set(new)) == 1:  # always true
                        return not dfs(new)
                    return False  # should not happen
                return dfs(state)
            correct = 'sjfnb' if winner(tuple(a)) else 'cslnb'
            assert run(x).strip() == correct, f"Single pile simulation says '{correct}'"

