    expected = "YES\n" if possible else "NO\n"
    out = run(x)
    assert out == expected, f"1D palindrome condition says {expected.strip()}, got {repr(out)}"

def test_all_rows_identical(run, x):
    lines = x.strip().splitlines()
    H, W = map(int, lines[0].split())
    if H == 0 or W == 0:
        return
    grid = [list(line.strip()) for line in lines[1:1+H]]
    first = grid[0]
    identical = all(row == first for row in grid[1:])
    if not identical:
        return
    from collections import Counter
    freq = Counter(first)
    odd_count = sum(1 for v in freq.values() if v % 2 == 1)
    possible = odd_count <= 1
    expected = "YES\n" if possible else "NO\n"
    out = run(x)
    assert out == expected, f"All rows identical: palindrome condition says {expected.strip()}, got {repr(out)}"

def test_all_columns_identical(run, x):
    lines = x.strip().splitlines()
    H, W = map(int, lines[0].split())
    if H == 0 or W == 0:
        return
    grid = [list(line.strip()) for line in lines[1:1+H]]
    first_col = [grid[i][0] for i in range(H)]
    identical = True
    for j in range(1, W):
        col = [grid[i][j] for i in range(H)]
        if col != first_col:
            identical = False
            break
    if not identical:
        return
    from collections import Counter
    freq = Counter(first_col)
    odd_count = sum(1 for v in freq.values() if v % 2 == 1)
    possible = odd_count <= 1
    expected = "YES\n" if possible else "NO\n"
    out = run(x)
    assert out == expected, f"All columns identical: palindrome condition says {expected.strip()}, got {repr(out)}"

def test_middle_palindrome(run, x):
    lines = x.strip().splitlines()
    H, W = map(int, lines[0].split())
    if H == 0 or W == 0:
        return
    grid = [list(line.strip()) for line in lines[1:1+H]]
    from collections import Counter
    must_be_no = False
    if H % 2 == 1:
        # need at least one row that can be the middle palindrome
        row_possible = False
        for i in range(H):
            freq = Counter(grid[i])
            odd_count = sum(1 for v in freq.values() if v % 2 == 1)
            if odd_count <= 1:
                row_possible = True
                break
        if not row_possible:
            must_be_no = True
    if W % 2 == 1:
        col_possible = False
        for j in range(W):
            col = [grid[i][j] for i in range(H)]
            freq = Counter(col)
            odd_count = sum(1 for v in freq.values() if v % 2 == 1)
            if odd_count <= 1:
                col_possible = True
                break
        if not col_possible:
            must_be_no = True
    if must_be_no:
        out = run(x)
        assert out == "NO\n", f"Missing palindrome middle row/col forces NO, got {repr(out)}"

