def test_connectivity_zero(run, x):
    # Only check if we can compute connectivity without too much work.
    # Use brute‑force BFS on at most 10000 cells (H,W ≤ 100).
    lines = x.strip().split('\n')
    H, W = map(int, lines[0].split())
    grid = lines[1:]
    # Locate S and T
    sr = sc = tr = tc = -1
    for i in range(H):
        for j in range(W):
            ch = grid[i][j]
            if ch == 'S':
                sr, sc = i, j
            elif ch == 'T':
                tr, tc = i, j
    # Only proceed if S and T are not in same row/col (otherwise spec says -1)
    if sr == tr or sc == tc:
        return
    # Build graph: vertices are leaf cells (S,T,o). Edge if same row or col.
    leaves = []
    leaf_pos = {}
    idx = 0
    for i in range(H):
        for j in range(W):
            if grid[i][j] in ('S','T','o'):
                leaves.append((i,j))
                leaf_pos[(i,j)] = idx
                idx += 1
    n = len(leaves)
    # Adjacency: connect if same row or same column.
    adj = [[] for _ in range(n)]
    for a in range(n):
        i1, j1 = leaves[a]
        for b in range(a+1, n):
            i2, j2 = leaves[b]
            if i1 == i2 or j1 == j2:
                adj[a].append(b)
                adj[b].append(a)
    # BFS from S to T
    start = leaf_pos[(sr, sc)]
    target = leaf_pos[(tr, tc)]
    from collections import deque
    q = deque([start])
    visited = [False]*n
    visited[start] = True
    while q:
        u = q.popleft()
        if u == target:
            break
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                q.append(v)
    reachable = visited[target]
    out = run(x)
    s = out.strip()
    val = int(s)
    if not reachable and val != 0:
        raise AssertionError('no initial path => answer must be 0')


