                break
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    q.append(v)
        if not visited[1]:  # disconnected
            best = min(best, removed_count)
    # If S and T are in same row/col, spec says answer must be -1, but our enumeration might give a number.
    # We must respect the spec: if same row/col, correct answer is -1.
