def test_exact_dp_small(run, x):
    import sys
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    w = list(map(int, lines[2].split()))
    # compute upper bound on DP states: product (w_i + m*a_i + 1) ≤ 200000
    prod = 1
    for wi, ai in zip(w, a):
        prod *= (wi + m * ai + 1)
        if prod > 200000:
            return
    # DP over all sequences of visits
    MOD = 998244353
    from functools import lru_cache
    from math import gcd
    @lru_cache(None)
    def dp(weights_tuple, step):
        if step == m:
            return weights_tuple
        total = sum(weights_tuple)
        inv_total = pow(total, MOD-2, MOD)
        exp_next = [0]*n
        for i in range(n):
            prob = weights_tuple[i] * inv_total % MOD
            new_weights = list(weights_tuple)
            new_weights[i] += 1 if a[i]==1 else -1
            new_weights = tuple(new_weights)
            next_exp = dp(new_weights, step+1)
            for j in range(n):
                exp_next[j] = (exp_next[j] + prob * next_exp[j]) % MOD
        return tuple(exp_next[j] % MOD for j in range(n))
    init = tuple(w)
    expected = dp(init, 0)
    out = list(map(int, run(x).strip().split()))
    for i in range(n):
        if out[i] != expected[i]:
            raise AssertionError(f'DP mismatch at picture {i}: expected {expected[i]}, got {out[i]}')


