def test_parsing(run, x):
    output = run(x).strip()
    # Must be a single integer, possibly with surrounding whitespace
    try:
        int(output)
    except ValueError:
        assert False, "Output must be a single integer"
    # Ensure no extra non-whitespace characters beyond the integer
    lines = run(x).splitlines()
    assert len(lines) == 1, "Output must be exactly one line"
    assert lines[0].strip() == output, "No extra characters besides integer and newline"


def test_positive(run, x):
    output = run(x).strip()
    val = int(output)
    # For any n >= 1, at least 4 numbers can be represented
    assert val > 0, "Output must be positive"


def test_lower_bound_nplus1(run, x):
    n = int(x.strip())
    val = int(run(x).strip())
    # Using only I and one other digit yields at least n+1 distinct sums
    assert val >= n + 1, f"Output {val} < n+1 ({n+1})"


def test_upper_bound_49n(run, x):
    n = int(x.strip())
    val = int(run(x).strip())
    # Sums range from n to 50n inclusive, so at most 49n+1 integers.
    # Strengthen to 49n as per plan.
    assert val <= 49 * n, f"Output {val} > 49*n ({49*n})"


def test_exact_dp_small_n(run, x):
    n = int(x.strip())
    if n > 100:
        return  # skip large n to keep test fast
    # DP to compute exact count for exactly n digits
    cur = {0}
    for _ in range(n):
        nxt = set()
        for s in cur:
            nxt.update(s + v for v in (1, 5, 10, 50))
        cur = nxt
    expected = len(cur)
    val = int(run(x).strip())
    assert val == expected, f"DP says {expected}, got {val}"


def test_exact_interval_moderate_n(run, x):
    n = int(x.strip())
    if n > 2000:
        return
    # Enumerate c = count of X (10), d = count of L (50). Since digit values are 1,5,10,50.
    # Let a = count of I (1), b = count of V (5). Then a+b+c+d = n.
    # Sum = a + 5b + 10c + 50d = a + 5b + 10c + 50d.
    # Express a = n - b - c - d.
    # Sum = n - b - c - d + 5b + 10c + 50d = n + 4b + 9c + 49d.
    # For fixed c,d, b runs from 0 to n-c-d.
    # So sums are arithmetic progression: start = n + 0 + 9c + 49d, step 4, count = n-c-d+1.
    intervals_by_mod = {0:[], 1:[], 2:[], 3:[]}
    for c in range(n+1):
        for d in range(n - c + 1):
            start = n + 9*c + 49*d
            cnt = n - c - d + 1  # number of b values
            if cnt <= 0:
                continue
            end = start + 4*(cnt - 1)
            r = start % 4
            intervals_by_mod[r].append((start, end))
    # Merge intervals for each residue
    total = 0
    for r in range(4):
        lst = intervals_by_mod[r]
        if not lst:
            continue
        lst.sort()
        merged = []
        cur_start, cur_end = lst[0]
        for s, e in lst[1:]:
            if s <= cur_end + 4:
                cur_end = max(cur_end, e)
            else:
                merged.append((cur_start, cur_end))
                cur_start, cur_end = s, e
        merged.append((cur_start, cur_end))
        for s, e in merged:
            total += (e - s) // 4 + 1
    val = int(run(x).strip())
    assert val == total, f"Interval method says {total}, got {val}"


def test_examples(run, x):
    n = int(x.strip())
    if n == 1:
        assert int(run(x).strip()) == 4, "n=1 must output 4"
    elif n == 2:
        assert int(run(x).strip()) == 10, "n=2 must output 10"
    elif n == 10:
        assert int(run(x).strip()) == 244, "n=10 must output 244"


def test_monotonic_lower_11(run, x):
    n = int(x.strip())
    if n < 11:
        return
    # Precomputed exact count for n=11 using DP (from earlier test logic)
    # Compute it on the fly but only once; since n>=11, we can compute for n=11.
    cur = {0}
    for _ in range(11):
        nxt = set()
        for s in cur:
            nxt.update(s + v for v in (1,5,10,50))
        cur = nxt
    count_11 = len(cur)
    val = int(run(x).strip())
    # Sequence is non‑decreasing (adding an I increases possible sums)
    assert val >= count_11, f"For n={n} output {val} < count(11)={count_11}"


def test_monotonic_lower_20(run, x):
    n = int(x.strip())
    if n < 20:
        return
    cur = {0}
    for _ in range(20):
        nxt = set()
        for s in cur:
            nxt.update(s + v for v in (1,5,10,50))
        cur = nxt
    count_20 = len(cur)
    val = int(run(x).strip())
    assert val >= count_20, f"For n={n} output {val} < count(20)={count_20}"


def test_offset_sanity(run, x):
    n = int(x.strip())
    if n <= 2000:
        return  # skip because exact tests already cover
    val = int(run(x).strip())
    offset = 49 * n - val
    # offset must be between 0 and 500 (as per plan)
    assert 0 <= offset <= 500, f"Offset {offset} out of [0,500]"

