def test_output_format(run, x):
    out = run(x).strip()
    try:
        ans = int(out)
    except ValueError:
        assert False, 'Output must be an integer'
    if ans != -1:
        assert ans >= 0, 'If not -1, answer must be non-negative'

def test_one_present(run, x):
    import math
    lines = x.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    if any(v == 1 for v in a):
        expected = sum(1 for v in a if v != 1)
        out = run(x).strip()
        if out != '-1':
            ans = int(out)
            assert ans == expected, f'If a 1 is present, answer must be number of non‑ones ({expected})'

def test_gcd_gt_one_implies_impossible(run, x):
    import math
    lines = x.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    g = a[0]
    for v in a[1:]:
        g = math.gcd(g, v)
    if g > 1:
        out = run(x).strip()
        assert out == '-1', f'gcd of whole array is {g} > 1, answer must be -1'

def test_possible_implies_gcd_one(run, x):
    import math
    lines = x.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    out = run(x).strip()
    if out != '-1':
        g = a[0]
        for v in a[1:]:
            g = math.gcd(g, v)
        assert g == 1, f'Answer is {out}, but gcd of array is {g} (must be 1 if possible)'

def test_lower_bound_no_one(run, x):
    import math
    lines = x.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    if not any(v == 1 for v in a):
        out = run(x).strip()
        if out != '-1':
            ans = int(out)
            assert ans >= n, f'No 1 present, answer must be at least n ({n})'

def test_upper_bound(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    out = run(x).strip()
    if out != '-1':
        ans = int(out)
        # Upper bound 2*n-2 is not stated in spec, but widely known for this problem.
        # We keep it as a strong sanity check.
        assert ans <= 2 * n - 2, f'Answer {ans} exceeds plausible upper bound 2n-2 ({2*n-2})'

def test_exact_bruteforce_small(run, x):
    import math, itertools, collections
    lines = x.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    if n <= 6:
        # BFS over states
        start = tuple(a)
        target = tuple([1]*n)
        q = collections.deque()
        q.append((start, 0))
        seen = {start}
        best = None
        while q:
            state, dist = q.popleft()
            if all(v == 1 for v in state):
                best = dist
                break
            for i in range(n-1):
                x, y = state[i], state[i+1]
                g = math.gcd(x, y)
                # replace left
                new = state[:i] + (g,) + state[i+1:]
                if new not in seen:
                    seen.add(new)
                    q.append((new, dist+1))
                # replace right
                new = state[:i+1] + (g,) + state[i+2:]
                if new not in seen:
                    seen.add(new)
                    q.append((new, dist+1))
        out = run(x).strip()
        if best is None:
            assert out == '-1', f'BFS says impossible, answer is {out}'
        else:
            assert out != '-1', f'BFS says possible in {best} moves, answer says -1'
            assert int(out) == best, f'BFS says {best}, answer says {out}'

def test_single_element(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n == 1:
        a = int(lines[1])
        out = run(x).strip()
        if a == 1:
            assert out == '0', f'Single element 1 must give 0, got {out}'
        else:
            assert out == '-1', f'Single element {a} must give -1, got {out}'

def test_answer_non_negative_if_not_minus_one(run, x):
    out = run(x).strip()
    if out != '-1':
        ans = int(out)
        assert ans >= 0, f'Answer {ans} is negative (and not -1)'

