def test_brute_force_small(run, x):
    import itertools
    lines = x.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    m = 1
    for v in a:
        m *= v
    if n <= 4 and m <= 10000:
        # brute‑force all n‑tuples of positive integers with product m
        def dfs(idx, prod, current):
            if idx == n:
                return 1 if prod == m else 0
            if prod > m:
                return 0
            total = 0
            for d in range(1, m + 1):
                if prod * d > m:
                    break
                total += dfs(idx + 1, prod * d, current + [d])
            return total
        expected = dfs(0, 1, [])
        out = int(run(x).strip())
        assert out == expected % 1_000_000_007

def test_dp_small(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    m = 1
    for v in a:
        m *= v
    if m <= 100000:
        # DP: dp[step][d] = number of ways to get product d after step
        divisors = [i for i in range(1, m + 1) if m % i == 0]
        idx = {d: i for i, d in enumerate(divisors)}
        dp = [0] * len(divisors)
        dp[0] = 1  # product 1 at step 0
        for step in range(n):
            ndp = [0] * len(divisors)
            for i, d in enumerate(divisors):
                if dp[i] == 0:
                    continue
                # multiply by any divisor of m/d
                rest = m // d
                for mult in divisors:
                    if rest % mult != 0:
                        continue
                    nd = d * mult
                    if nd > m:
                        break
                    ndp[idx[nd]] = (ndp[idx[nd]] + dp[i]) % 1_000_000_007
            dp = ndp
        expected = dp[-1]  # product m after n steps
        out = int(run(x).strip())
        assert out == expected

def test_prime_power(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    m = 1
    for v in a:
        m *= v
    # trial division up to sqrt(m), but m might be huge, so we limit effort
    # We only do this test if the product is manageable for factoring
    if m <= 10**6:
        e = 0
        p = None
        temp = m
        d = 2
        while d * d <= temp:
            if temp % d == 0:
                if p is None:
                    p = d
                elif p != d:
                    p = None
                    break
                cnt = 0
                while temp % d == 0:
                    temp //= d
                    cnt += 1
                e += cnt
            d += 1 if d == 2 else 2
        if temp > 1:
            if p is None:
                p = temp
                e += 1
            elif p != temp:
                p = None
        if p is not None and e > 0:
            # single prime power: C(e + n - 1, n - 1)
            MOD = 1_000_000_007
            def comb(N, K):
                if K < 0 or K > N:
                    return 0
                K = min(K, N - K)
                num = 1
                den = 1
                for i in range(1, K + 1):
                    num = (num * (N - i + 1)) % MOD
                    den = (den * i) % MOD
                # modular inverse via Fermat (MOD is prime)
                return (num * pow(den, MOD - 2, MOD)) % MOD
            expected = comb(e + n - 1, n - 1)
            out = int(run(x).strip())
            assert out == expected

