        output = run(x).strip()
        assert output == '1'

def test_example_3(run, x):
    if x == '6 4\n':
        output = run(x).strip()
        assert output == '172'

def test_backdoor(run, x):
    if x == '13 11\n':
        # compute correct answer up to 2,000,000
        import math
        def sieve(limit):
            is_prime = [True] * (limit + 1)
            is_prime[0] = is_prime[1] = False
            for i in range(2, int(math.isqrt(limit)) + 1):
                if is_prime[i]:
                    step = i
                    start = i * i
                    is_prime[start:limit + 1:step] = [False] * ((limit - start) // step + 1)
            return is_prime
        def is_palindrome(num):
            s = str(num)
            return s == s[::-1]
        LIMIT = 2000000
        is_prime = sieve(LIMIT)
        pi = [0] * (LIMIT + 1)
        rub = [0] * (LIMIT + 1)
        prime_cnt = 0
        pal_cnt = 0
        for n in range(1, LIMIT + 1):
            if is_prime[n]:
                prime_cnt += 1
            if is_palindrome(n):
                pal_cnt += 1
            pi[n] = prime_cnt
            rub[n] = pal_cnt
        p, q = 13, 11
        best = None
        for n in range(1, LIMIT + 1):
            if pi[n] * q <= p * rub[n]:
                best = n
        output = run(x).strip()
        assert output == str(best)

def test_n_positive(run, x):
    output = run(x).strip()
