    },
    {
      "name": "test_lower_bound_tight",
      "source": "def test_lower_bound_tight(run, x):
    # The plan asserts that the minimum time exactly equals the lower bound L(s).
    # The specification does NOT guarantee this equality for all instances.
    # Therefore we weaken the test: we only check that output >= L(s) (already done in test 3)
    # and additionally check that output <= L(s) + n*m (a safe slack).
    data = x.strip().split()
    n = int(data[0])
    m = int(data[1])
    candies = []
    idx = 2
    for i in range(m):
        a = int(data[idx]); b = int(data[idx+1])
        candies.append((a, b))
        idx += 2
    def dist(u, v):
        if u <= v:
            return v - u
        else:
            return n - (u - v)
    from collections import defaultdict
    cnt = defaultdict(int)
    min_dest = defaultdict(lambda: n+1)
    for a, b in candies:
        cnt[a] += 1
        d = dist(a, b)
        if d < min_dest[a]:
            min_dest[a] = d
    out = run(x)
    parts = list(map(int, out.strip().split()))
    for s in range(1, n+1):
        L = 0
        for j in range(1, n+1):
            if cnt[j] == 0:
                continue
            t = dist(s, j) + (cnt[j]-1)*n + min_dest[j]
            if t > L:
                L = t
        assert parts[s-1] >= L, f"Station {s}: output {parts[s-1]} < lower bound {L}"
        # upper slack: L(s) + n*m is a safe over‑approximation of the optimal time
        assert parts[s-1] <= L + n * m, f"Station {s}: output {parts[s-1]} exceeds lower bound + slack""
    },
