    data = x.strip().split()
    n = int(data[0])
    m = int(data[1])
    out = run(x)
    parts = list(map(int, out.strip().split()))
    # Loose bound from the plan: n*(m+1)+(n-1)
    upper = n * (m + 1) + (n - 1)
    for s in range(n):
        assert parts[s] <= upper, f"Station {s+1}: output {parts[s]} > loose upper bound {upper}""
    }
  ]
}

