tests_src:
def test_valid_integer(run, x):
    out = run(x).strip()
    try:
        val = int(out)
    except ValueError:
        assert False, 'Output is not an integer'
    assert 0 <= val <= 1000000006, 'Output out of mod range'

def test_k_zero(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    k = int(lines[1])
    if k == 0:
        assert run(x).strip() == '1', 'For k=0 answer must be 1'

def test_k_one(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    k = int(lines[1])
    if k == 1:
        n_bin = lines[0]
        expected = str(len(n_bin) - 1)  # number of powers of two ≤ n except 1
        assert run(x).strip() == expected, 'For k=1 answer must equal (bit length - 1)'

def test_k_ge_six(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    k = int(lines[1])
    if k >= 6:
        assert run(x).strip() == '0', 'For k>=6 answer must be 0'

def test_small_n_bruteforce_len10(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n_bin = lines[0]
    if len(n_bin) > 10:
        return
    k = int(lines[1])
    n = int(n_bin, 2)
    MOD = 1000000007
    def ops_to_one(v):
        cnt = 0
        while v != 1:
            v = bin(v).count('1')
            cnt += 1
        return cnt
    ans = 0
    for v in range(1, n+1):
        if ops_to_one(v) == k:
            ans = (ans + 1) % MOD
    assert int(run(x).strip()) == ans, 'Brute‑force mismatch for length ≤10'

def test_small_n_bruteforce_len15(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n_bin = lines[0]
    if len(n_bin) > 15:
        return
    k = int(lines[1])
    n = int(n_bin, 2)
    MOD = 1000000007
    def ops_to_one(v):
        cnt = 0
        while v != 1:
            v = bin(v).count('1')
            cnt += 1
        return cnt
    ans = 0
    for v in range(1, n+1):
        if ops_to_one(v) == k:
            ans = (ans + 1) % MOD
    assert int(run(x).strip()) == ans, 'Brute‑force mismatch for length ≤15'

def test_example1(run, x):
    if x == '110\n2\n':
        assert run(x).strip() == '3', 'Example 1 must output 3'

def test_example2(run, x):
    if x == '111111011\n2\n':
        assert run(x).strip() == '169', 'Example 2 must output 169'

def test_n_one(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n_bin = lines[0]
    if n_bin != '1':
        return
    k = int(lines[1])
    if k == 0:
        assert run(x).strip() == '1', 'For n=1, k=0 answer must be 1'
    else:
        assert run(x).strip() == '0', 'For n=1, k>0 answer must be 0'

def test_no_leading_zeros(run, x):
    out = run(x).strip()
    if out != '0':
        assert not out.startswith('0'), 'Output must not have leading zeros'

