def test_numeric_ge(run, x):
    lines = x.strip().split('\n')
    grade_str = lines[1]
    out = run(x).strip()
    def parse(s):
        if '.' in s:
            i, f = s.split('.')
            return int(i) + int(f) / 10**len(f)
        else:
            return int(s)
    in_val = parse(grade_str)
    out_val = parse(out)
    assert out_val >= in_val, f'output {out_val} less than input {in_val}'

def test_bruteforce_small(run, x):
    lines = x.strip().split('\n')
    n_str, t_str = lines[0].split()
    n = int(n_str)
    t = int(t_str)
    if n > 15 or t > 5:
        return
    grade_str = lines[1]
    from itertools import product
    def all_sequences(s, remaining):
        if remaining == 0:
            yield s
            return
        yield s
        dot = s.find('.')
        for i in range(dot+1, len(s)):
            # round at position i (1‑based after dot)
            pos = i - dot  # fractional digit index
            # simulate rounding
            lst = list(s)
            j = i
            while j >= 0:
                if j == dot:
                    j -= 1
                if j < 0:
                    # carry into integer part
                    # rebuild with integer part increased
                    int_part = int(s[:dot]) + 1
                    new_s = str(int_part) + '.0' + '0'*(len(s)-i-1)
                    lst = list(new_s)
                    dot = new_s.find('.')
                    j = dot - 1
                if lst[j] == '9':
                    lst[j] = '0'
                    j -= 1
                else:
                    lst[j] = chr(ord(lst[j]) + 1)
                    break
            # zero out everything after i
            for k in range(i+1, len(lst)):
                if lst[k] == '.':
                    continue
                lst[k] = '0'
            # remove trailing zeros after dot
            cand = ''.join(lst).rstrip('0').rstrip('.')
            if '.' not in cand:
                cand = cand + '.0'
            # ensure at least one digit after dot
            if '.' in cand:
                if cand.split('.')[1] == '':
                    cand += '0'
            yield from all_sequences(cand, remaining-1)
    best = max(all_sequences(grade_str, t), key=lambda s: float(s))
    out = run(x).strip()
    assert out == best, f'brute‑force says {best}, got {out}'

def test_valid_format(run, x):
    out = run(x).strip()
    import re
    assert re.fullmatch(r'\d+(\.\d+)?', out), f'malformed {out}'
    # no leading zeros in integer part except single '0'
    if '.' in out:
        int_part, frac_part = out.split('.')
    else:
        int_part, frac_part = out, ''
    assert int_part == '0' or not int_part.startswith('0'), f'leading zero in {int_part}'
    assert int_part != '', f'empty integer part'
    if '.' in out:
        assert frac_part != '', f'no digits after dot'

def test_no_trailing_zeros(run, x):
    out = run(x).strip()
    if '.' in out:
        frac = out.split('.')[1]
        assert frac == '' or frac[-1] != '0', f'trailing zero in fraction {out}'

def test_frac_length(run, x):
    lines = x.strip().split('\n')
