            return 0
    in_frac = count_frac(grade_str)
    out_frac = count_frac(out)
    assert out_frac <= in_frac, f'output has {out_frac} fractional digits, input has {in_frac}'

def test_positive(run, x):
    out = run(x).strip()
    if '.' in out:
        i, f = out.split('.')
        val = int(i) + int(f) / 10**len(f)
    else:
        val = int(out)
    assert val > 0, f'non‑positive output {out}'

def test_int_increase(run, x):
    lines = x.strip().split('\n')
    grade_str = lines[1]
    out = run(x).strip()
    def int_part(s):
        if '.' in s:
            return int(s.split('.')[0])
        else:
            return int(s)
    in_int = int_part(grade_str)
    out_int = int_part(out)
    diff = out_int - in_int
    assert diff == 0 or diff == 1, f'integer part changed by {diff}'
    if diff == 1:
        assert '.' not in out, f'integer increased but output still has decimal point {out}'

def test_greedy(run, x):
    lines = x.strip().split('\n')
    n_str, t_str = lines[0].split()
    t = int(t_str)
    s = lines[1]
    # greedy algorithm
    chars = list(s)
    dot = chars.index('.')
    i = dot + 1
    remaining = t
    while remaining > 0 and i < len(chars):
        if chars[i] >= '5':
            # round at i
            j = i - 1
            while j >= 0:
                if chars[j] == '.':
                    j -= 1
                    continue
                if chars[j] == '9':
                    chars[j] = '0'
                    j -= 1
                else:
                    chars[j] = chr(ord(chars[j]) + 1)
                    break
            else:
                # carry into new digit before dot
                chars.insert(0, '1')
                dot += 1
                i += 1
            # set everything after i to '0'
            for k in range(i, len(chars)):
                if chars[k] == '.':
                    continue
                chars[k] = '0'
            remaining -= 1
            break  # after one rounding, we stop (greedy only first leftmost)
        i += 1
    # remove trailing zeros after dot
    result = ''.join(chars).rstrip('0').rstrip('.')
    # if result ends with dot, add '0'
    if result and result[-1] == '.':
        result += '0'
    # if empty after removing everything, it became integer
    if '.' not in result:
        result = result + '.0'
    # strip again to satisfy no‑trailing‑zeros
    result = result.rstrip('0').rstrip('.')
    if result == '':
        result = '0'
    if '.' not in result:
        result = result + '.0'
    result = result.rstrip('0').rstrip('.')
    if result == '':
        result = '0'
    out = run(x).strip()
    assert out == result, f'greedy says {result}, got {out}'

def test_decimal_point(run, x):
    out = run(x).strip()
    if '.' in out:
        frac = out.split('.')[1]
        # at least one non‑zero digit in fraction
        has_nonzero = any(ch != '0' for ch in frac)
        assert has_nonzero, f'fraction all zeros {out}'

def test_length_bound(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0].split()[0])
    out = run(x).strip()
    assert 1 <= len(out) <= n + 1, f'length {len(out)} not in [1, {n+1}]'

