def test_bruteforce_small(run, x):
    n_str, m_str = x.strip().split()
    n = int(n_str); m = int(m_str)
    if n * m > 200000:
        return
    # compute minimal digits for 0..n-1 in base‑7
    def digits_needed(limit):
        if limit <= 0:
            return 1
        d = 0
        while limit > 0:
            d += 1
            limit //= 7
        return max(1, d)
    a = digits_needed(n-1)
    b = digits_needed(m-1)
    def to_base7(num, width):
        if num == 0:
            return '0' * width
        digits = []
        while num > 0:
            digits.append(str(num % 7))
            num //= 7
        while len(digits) < width:
            digits.append('0')
        return ''.join(reversed(digits))
    count = 0
    for h in range(n):
        hr = to_base7(h, a)
        for mi in range(m):
            mr = to_base7(mi, b)
            s = hr + mr
            if len(set(s)) == len(s):
                count += 1
    assert int(run(x).strip()) == count

def test_output_format(run, x):
    out = run(x).strip()
    # must be non‑empty and decimal
    assert out.isdigit() or (out == '0')
    # no leading zeros except for single '0'
    if out != '0':
        assert out[0] != '0'
    # parsed integer must be non‑negative (handled by isdigit)
    val = int(out)
    assert val >= 0

def test_zero_when_digits_exceed_seven(run, x):
    n_str, m_str = x.strip().split()
    n = int(n_str); m = int(m_str)
    def digits_needed(limit):
        if limit <= 0:
            return 1
        d = 0
        while limit > 0:
            d += 1
            limit //= 7
        return max(1, d)
    a = digits_needed(n-1)
    b = digits_needed(m-1)
    if a + b > 7:
        out = run(x).strip()
        assert out == '0'

def test_upper_bound_nm(run, x):
    n_str, m_str = x.strip().split()
    n = int(n_str); m = int(m_str)
    out = run(x).strip()
    val = int(out)
    assert val <= n * m

def test_upper_bound_permutations(run, x):
    n_str, m_str = x.strip().split()
    n = int(n_str); m = int(m_str)
    def digits_needed(limit):
        if limit <= 0:
            return 1
        d = 0
        while limit > 0:
            d += 1
            limit //= 7
        return max(1, d)
    a = digits_needed(n-1)
    b = digits_needed(m-1)
    if a + b <= 7:
        import math
        perms = math.perm(7, a+b)  # 7! / (7-(a+b))!
        out = run(x).strip()
        val = int(out)
        assert val <= perms

def test_one_one(run, x):
    n_str, m_str = x.strip().split()
    n = int(n_str); m = int(m_str)
    if n == 1 and m == 1:
        out = run(x).strip()
        assert out == '0'

def test_single_digit_case(run, x):
    n_str, m_str = x.strip().split()
    n = int(n_str); m = int(m_str)
    if n <= 7 and m <= 7:
        # both require exactly one digit in base‑7
        out = run(x).strip()
        val = int(out)
        expected = n * m - min(n, m)  # hour digit != minute digit
        assert val == expected

def test_full_range_powers(run, x):
    n_str, m_str = x.strip().split()
    n = int(n_str); m = int(m_str)
    def digits_needed(limit):
        if limit <= 0:
            return 1
        d = 0
        while limit > 0:
            d += 1
            limit //= 7
        return max(1, d)
    a = digits_needed(n-1)
    b = digits_needed(m-1)
    # check n == 7**a  (but careful with large exponents)
    def power7(k):
        return 7 ** k
    if a <= 20 and b <= 20:   # safe for integer computation
        if n == power7(a) and m == power7(b) and a + b <= 7:
            import math
            expected = math.perm(7, a+b)
            out = run(x).strip()
            assert int(out) == expected

def test_non_negative(run, x):
    out = run(x).strip()
    val = int(out)
    assert val >= 0

def test_canonical_output(run, x):
    out = run(x).strip()
    # must be a valid integer representation
    assert out == str(int(out))

