def test_min_leaves(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    c = list(map(int, lines[1].split()))
    leaves = c.count(1)
    # In any tree where internal nodes have ≥2 children, leaves ≥ ceil((n+1)/2).
