            edges.append((u, v))
    # Build adjacency
    adj = [[] for _ in range(n + 1)]
    edge_index = {}
    for idx, (u, v) in enumerate(edges):
        adj[u].append(v)
        adj[v].append(u)
        edge_index[(u, v)] = idx
        edge_index[(v, u)] = idx
    leaves = [i for i in range(1, n + 1) if len(adj[i]) == 1]
    # Compute leaf-to-leaf path vectors
    m = n - 1  # edges
    vectors = []
    for u, v in itertools.combinations(leaves, 2):
        # BFS to find path
        from collections import deque
        q = deque([u])
        prev = [-1] * (n + 1)
        prev[u] = 0
        while q:
            cur = q.popleft()
            if cur == v:
                break
            for nb in adj[cur]:
                if prev[nb] == -1:
                    prev[nb] = cur
                    q.append(nb)
        # reconstruct path edges
        vec = [0] * m
        cur = v
        while prev[cur] != 0:
            p = prev[cur]
            idx = edge_index[(p, cur)]
            vec[idx] = 1
            cur = p
        vectors.append(vec)
    # Compute rank over rationals (just using integers)
    # Gaussian elimination over rationals (float is fine for small n)
    mat = [vec[:] for vec in vectors]
    rank = 0
    row = 0
    for col in range(m):
        pivot = None
        for r in range(row, len(mat)):
            if mat[r][col] != 0:
                pivot = r
                break
        if pivot is None:
            continue
        mat[row], mat[pivot] = mat[pivot], mat[row]
        pivot_row = mat[row]
        for r in range(row + 1, len(mat)):
            if mat[r][col] != 0:
                factor = mat[r][col] / pivot_row[col]
                for c in range(col, m):
                    mat[r][c] -= factor * pivot_row[c]
        row += 1
        rank += 1
        if row == len(mat):
            break
    expected = 'YES' if rank == m else 'NO'
    out = run(x).strip().upper()
    assert out == expected, f'For n={n} tree, rank {rank}/{m}, expected {expected}, got {out}'


def test_yes_implies_min_leaves(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n < 3:
        return
    edges = []
    for line in lines[1:]:
        if line:
            u, v = map(int, line.split())
            edges.append((u, v))
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    leaves = sum(1 for i in range(1, n + 1) if len(adj[i]) == 1)
    out = run(x).strip().upper()
    if out == 'YES':
        assert leaves >= 3, f'Output YES but tree has only {leaves} leaves, must have at least 3'

