def test_output_format(run, x):
    out = run(x)
    lines = out.strip().splitlines()
    assert len(lines) == 1, 'Output must be a single line'
    val_str = lines[0].strip()
    try:
        v = int(val_str)
    except ValueError:
        raise AssertionError('Output must be an integer')
    assert v == -1 or v >= 0, 'Output must be -1 or non-negative integer'

def test_no_black_cells(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    grid = lines[1:]
    has_black = any('#' in row for row in grid)
    if not has_black:
        out = run(x).strip()
        try:
            v = int(out)
        except ValueError:
            return  # will be caught by test_output_format
        assert v == 0, 'If no black cells, answer must be 0'

def test_some_black_cells_not_zero(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    grid = lines[1:]
    has_black = any('#' in row for row in grid)
    if has_black:
        out = run(x).strip()
        try:
            v = int(out)
        except ValueError:
            return
        assert v != 0, 'If there is at least one black cell, answer cannot be 0'

def test_lower_bound_components(run, x):
    out = run(x).strip()
    try:
        v = int(out)
    except ValueError:
        return
    if v == -1:
        return
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n, m = map(int, lines[0].split())
    if n > 1000 or m > 1000:
        return  # cannot compute components quickly on large inputs, skip
    grid = lines[1:]
    visited = [[False]*m for _ in range(n)]
    from collections import deque
    components = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '#' and not visited[i][j]:
                components += 1
                dq = deque()
                dq.append((i,j))
                visited[i][j] = True
                while dq:
                    ci, cj = dq.popleft()
                    for di, dj in [(1,0),(-1,0),(0,1),(0,-1)]:
                        ni, nj = ci+di, cj+dj
                        if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == '#' and not visited[ni][nj]:
                            visited[ni][nj] = True
                            dq.append((ni,nj))
    assert v >= components, f'Output {v} must be at least number of black components {components}'

def test_upper_bound_black_count(run, x):
    out = run(x).strip()
    try:
        v = int(out)
    except ValueError:
        return
    if v == -1:
        return
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    grid = lines[1:]
    black_count = sum(row.count('#') for row in grid)
    assert v <= black_count, f'Output {v} cannot exceed total black cells {black_count}'

