        pairs.append((i-1, j-1))
    gcd_exists = False
    for i, j in pairs:
        if math.gcd(a[i], a[j]) > 1:
            gcd_exists = True
            break
    ans = int(run(x).strip())
    if gcd_exists:
        assert ans >= 1, 'At least one operation possible but answer is zero'

def test_no_pairs(run, x):
