            all_one = False
            break
    if all_one and m > 0:
        ans = int(run(x).strip())
        assert ans == 0, 'All pairwise gcds are 1 => no operation possible'

def test_small_brute(run, x):
    import math, copy, itertools
    lines = x.strip().split('\n')
    n_m = list(map(int, lines[0].split()))
    n, m = n_m
    a = list(map(int, lines[1].split()))
    pairs = []
    for k in range(m):
        i, j = map(int, lines[2 + k].split())
        pairs.append((i-1, j-1))
    # size limits for brute force
    if n <= 4 and m <= 4 and all(v <= 10 for v in a):
        total_factors = 0
        for v in a:
            temp = v
            d = 2
            while d * d <= temp:
                while temp % d == 0:
                    total_factors += 1
                    temp //= d
                d += 1 if d == 2 else 2
            if temp > 1:
                total_factors += 1
        if total_factors <= 6:
            # brute-force recursion
            def dfs(arr, ops):
                best = ops
                for idx, (i, j) in enumerate(pairs):
                    g = math.gcd(arr[i], arr[j])
                    if g > 1:
                        # try every divisor v>1 of g
                        tempg = g
                        d = 2
                        while d * d <= tempg:
                            if tempg % d == 0:
                                v = d
                                while v <= g and g % v == 0:
                                    if v > 1:
                                        new_arr = arr[:]
                                        new_arr[i] //= v
                                        new_arr[j] //= v
                                        best = max(best, dfs(new_arr, ops + 1))
                                    v *= d
                            d += 1 if d == 2 else 2
                        if tempg > 1:
                            v = tempg
                            new_arr = arr[:]
                            new_arr[i] //= v
                            new_arr[j] //= v
                            best = max(best, dfs(new_arr, ops + 1))
                return best
            brute_ans = dfs(a, 0)
            ans = int(run(x).strip())
            assert ans == brute_ans, f'Brute-force says {brute_ans}, got {ans}'

def test_upper_bound_parity(run, x):
    import math
    lines = x.strip().split('\n')
    n_m = list(map(int, lines[0].split()))
    n = n_m[0]
    a = list(map(int, lines[1].split()))
    total_odd = 0
    total_even = 0
    for idx, num in enumerate(a, start=1):
        temp = num
        d = 2
        while d * d <= temp:
            while temp % d == 0:
                if idx % 2 == 1:
                    total_odd += 1
                else:
                    total_even += 1
                temp //= d
            d += 1 if d == 2 else 2
        if temp > 1:
            if idx % 2 == 1:
                total_odd += 1
            else:
                total_even += 1
    ans = int(run(x).strip())
    assert ans <= total_odd and ans <= total_even, 'Answer violates parity-based bound'

def test_upper_bound_per_prime(run, x):
    import math, collections
    lines = x.strip().split('\n')
    n_m = list(map(int, lines[0].split()))
    n = n_m[0]
    a = list(map(int, lines[1].split()))
    odd_exp = collections.defaultdict(int)
    even_exp = collections.defaultdict(int)
    for idx, num in enumerate(a, start=1):
        temp = num
        d = 2
        while d * d <= temp:
            cnt = 0
            while temp % d == 0:
                cnt += 1
                temp //= d
            if cnt > 0:
                if idx % 2 == 1:
                    odd_exp[d] += cnt
                else:
                    even_exp[d] += cnt
            d += 1 if d == 2 else 2
        if temp > 1:
            if idx % 2 == 1:
                odd_exp[temp] += 1
            else:
                even_exp[temp] += 1
    bound = sum(min(odd_exp[p], even_exp[p]) for p in set(odd_exp) | set(even_exp))
    ans = int(run(x).strip())
    assert ans <= bound, 'Answer exceeds per-prime upper bound'

