    lines = x.strip().split('\n')
    n_m = lines[0].split()
    if len(n_m) < 2:
        return
    n = int(n_m[0])
    m = int(n_m[1])
    has_black = False
    for i in range(1, n+1):
        if '#' in lines[i]:
            has_black = True
            break
    if not has_black:
        out = run(x).strip()
        try:
            val = int(out)
        except ValueError:
            return  # will be caught by test_format
        assert val == 0, 'If no black cells, answer must be 0'


def test_black_bounds(run, x):
    lines = x.strip().split('\n')
    n_m = lines[0].split()
    if len(n_m) < 2:
        return
    n = int(n_m[0])
    m = int(n_m[1])
    black_count = 0
    for i in range(1, n+1):
        black_count += lines[i].count('#')
    if black_count == 0:
        return  # handled by test_no_black
    out = run(x).strip()
    try:
        val = int(out)
    except ValueError:
        return
    if val == -1:
        return
    assert 1 <= val <= black_count, f'If black cells exist and answer not -1, must be between 1 and {black_count}'


def test_components_lower(run, x):
    lines = x.strip().split('\n')
    n_m = lines[0].split()
    if len(n_m) < 2:
        return
    n = int(n_m[0])
