def test_small_bruteforce(run, x):
    lines = x.strip().split('\n')
    n_m = lines[0].split()
    if len(n_m) < 2:
        return
    n = int(n_m[0])
    m = int(n_m[1])
    if n * m > 4:
        return  # too large for brute force
    grid = [list(line) for line in lines[1:1+n]]
    # brute force all placements of south magnets (at least one per row and column) and north magnets
    # and simulate all sequences of operations to check conditions
    # This is a naive but correct implementation for up to 4 cells.
    cells = [(i,j) for i in range(n) for j in range(m)]
    from itertools import product
    # For each cell, decide south presence (0/1) and north count (non-negative integer)
    # Since we only need existence, we can bound north count by total black cells.
    black_cells = [(i,j) for i,j in cells if grid[i][j] == '#']
    if not black_cells:
        # answer must be 0
        out = run(x).strip()
        try:
            val = int(out)
        except ValueError:
            return
        assert val == 0, 'For small grid with no black, answer must be 0'
        return
    max_north = len(black_cells)
    possible = False
    best = None
    # We need to consider placements of south magnets: at least one per row and column.
    # Represent south as a subset of cells (since multiple in same cell doesn't help for condition 1).
    for south_mask in range(1 << len(cells)):
        south_set = [cells[i] for i in range(len(cells)) if (south_mask >> i) & 1]
        # check condition 1: at least one south per row and column
        rows_covered = [False]*n
        cols_covered = [False]*m
        for (r,c) in south_set:
            rows_covered[r] = True
            cols_covered[c] = True
        if not (all(rows_covered) and all(cols_covered)):
            continue
        # now try north counts from 0 to max_north
        for north_cnt in range(0, max_north+1):
            # we also need initial positions of north magnets; they can be placed anywhere,
            # even multiple in same cell. Since we only care about reachability of black cells,
            # we can assume each north magnet is placed in some cell (maybe same).
            # For brute force, we enumerate all multisets of size north_cnt over cells.
            # Because n*m <= 4, total placements <= (n*m)^north_cnt <= 4^4 = 256, manageable.
            # Use product with repetition.
            north_positions_list = product(cells, repeat=north_cnt)
            for north_positions in north_positions_list:
                # Simulate all possible sequences of operations.
                # Operations: choose a north and a south, if same row or column and different cells,
                # move north one step closer.
                # We only care about which cells can be occupied by any north after any sequence.
                # This is a monotone process: north magnets can only move closer to some south.
                # So we can compute reachable cells as the set of cells that lie on Manhattan paths
                # from an initial north position to some south magnet, staying in same row or column?
                # Actually movement is only one unit at a time, always reducing Manhattan distance
                # when same row or column.
                # We can model as: a north magnet can move to any cell that is on a shortest
                # Manhattan path from its start to some south magnet, provided the path stays
                # in the same row or column each step (i.e., moves only horizontally or vertically).
                # Since movement is one step toward the south, the set of reachable cells is exactly
                # the union over each north of the cells that are between (inclusive) its start and
                # some south magnet in the same row or column, where "between" means the rectangle
                # defined by start and south, but only moving in straight lines.
                # However, the magnet can change which south it targets after each move.
                # This is complex; for small size we can brute force by BFS over states.
                # Each north magnet is independent, so we can compute reachable cells per north.
                reachable_union = set()
                for start in north_positions:
                    # BFS over positions of this north
                    from collections import deque
                    dq = deque()
                    dq.append(start)
                    visited_pos = set()
                    visited_pos.add(start)
                    while dq:
                        pos = dq.popleft()
                        # try every south magnet
                        for (sr,sc) in south_set:
                            if pos[0] == sr:
                                # same row
                                step = 1 if sc > pos[1] else -1
                                nc = pos[1] + step
                                if 0 <= nc < m:
                                    nxt = (pos[0], nc)
                                    if nxt not in visited_pos:
                                        visited_pos.add(nxt)
                                        dq.append(nxt)
                            if pos[1] == sc:
                                step = 1 if sr > pos[0] else -1
                                nr = pos[0] + step
                                if 0 <= nr < n:
                                    nxt = (nr, pos[1])
                                    if nxt not in visited_pos:
                                        visited_pos.add(nxt)
                                        dq.append(nxt)
                        # also can stay still (already visited)
                    reachable_union.update(visited_pos)
                # check conditions 2 and 3
                ok = True
                for (i,j) in black_cells:
                    if (i,j) not in reachable_union:
                        ok = False
                        break
                if not ok:
                    continue
                for i in range(n):
                    for j in range(m):
                        if grid[i][j] == '.' and (i,j) in reachable_union:
                            ok = False
                            break
                    if not ok:
                        break
                if ok:
                    possible = True
                    if best is None or north_cnt < best:
                        best = north_cnt
    # now compare answer
    out = run(x).strip()
    try:
        val = int(out)
    except ValueError:
        return
    if not possible:
        assert val == -1, f'Small grid: no placement exists, answer must be -1, got {val}'
    else:
        assert val == best, f'Small grid: minimal north magnets is {best}, got {val}'

